const pathOrder=['my','zh','alevel','ged'];

let language = (document.documentElement.lang.startsWith('zh')?'zh':document.documentElement.lang==='my'?'my':'en');
let selectedPath = 'my';
const plain = html => { const el = document.createElement('div'); el.innerHTML = html; return el.textContent; };

function renderPath() {
  const path = translations[language].paths[selectedPath];
  document.querySelectorAll('[data-path]').forEach(button => {
    const selected = button.dataset.path === selectedPath;
    button.setAttribute('aria-selected', String(selected));
    button.tabIndex = selected ? 0 : -1;
  });
  document.querySelector('#pathway-panel').setAttribute('aria-labelledby', `tab-${selectedPath}`);
  document.querySelector('.panel-index').textContent = String(pathOrder.indexOf(selectedPath)+1).padStart(2,'0');
  document.querySelector('#pathTag').textContent = path.tag;
  document.querySelector('#pathTitle').textContent = path.title;
  document.querySelector('#pathDescription').textContent = path.description;
  document.querySelector('#pathList').replaceChildren(...path.list.map(text => {const li=document.createElement('li');li.textContent=text;return li;}));
  document.querySelector('#pathCta').innerHTML = path.cta;
  document.querySelector('#pathCta').href=document.querySelector('meta[name=site-base]').content+language+'/match/?qualification='+({my:'matriculation',zh:'chineseSchool',alevel:'alevel',ged:'ged'}[selectedPath]);
}

function setLanguage(next) {
  if (!translations[next]) return;
  language = next;
  document.documentElement.lang = {zh:'zh-CN',my:'my',en:'en'}[language];
  const t = translations[language];
  document.querySelectorAll('[data-t]').forEach(el => { if(t[el.dataset.t] !== undefined) el.innerHTML=t[el.dataset.t]; });
  document.querySelectorAll('[data-placeholder]').forEach(el => {el.placeholder=t[el.dataset.placeholder];});
  document.querySelectorAll('[data-lang]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.lang===language)));
  document.querySelector('.graduate').alt = t.imageAlt;
  document.querySelector('.menu-toggle').setAttribute('aria-label',t.menu);
  document.title = 'PyinNyar study abroad';
  document.querySelector('meta[name=description]').content = plain(t.heroDescription);
  try {localStorage.setItem('pyinnyar-language',language);} catch {}
  renderPath();
}

document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.lang)));
document.querySelectorAll('[data-path]').forEach(button=>{
  button.addEventListener('click',()=>{selectedPath=button.dataset.path;renderPath();});
  button.addEventListener('keydown',event=>{
    const keys=['ArrowRight','ArrowLeft','Home','End'];if(!keys.includes(event.key))return;
    event.preventDefault();const order=pathOrder;let index=order.indexOf(selectedPath);
    if(event.key==='Home')index=0;else if(event.key==='End')index=order.length-1;else index=(index+(event.key==='ArrowRight'?1:order.length-1))%order.length;
    selectedPath=order[index];renderPath();document.querySelector(`[data-path="${selectedPath}"]`).focus();
  });
});
document.querySelectorAll('[data-background]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();selectedPath=link.dataset.background;renderPath();document.querySelector('#pathways').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});document.querySelector(`[data-path="${selectedPath}"]`).focus({preventScroll:true});}));
const menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=document.querySelector('.nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});
document.querySelectorAll('.nav a').forEach(link=>link.addEventListener('click',()=>{document.querySelector('.nav').classList.remove('open');menu.setAttribute('aria-expanded','false');}));
setLanguage(language);
